const {chromium}=require('./browser/node_modules/playwright');
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1440,height:1000}});await p.goto('http://127.0.0.1:4181/ro/');await p.waitForSelector('.shop-footer');console.log(await p.locator('.shop-footer').evaluate(el=>({rect:el.getBoundingClientRect().toJSON(),style:getComputedStyle(el).display,links:el.querySelectorAll('a').length,text:el.textContent.slice(0,250),scroll:document.documentElement.scrollHeight})));await p.locator('.shop-footer').screenshot({path:'outputs/dracula-design-office/preview-footer.png'});await b.close();})();
